def lpHaarAncestors : (n : ℕ) → Fin (2 ^ n) → Finset LpHaarTreeIndex
  | 0, k => {⟨0, k⟩}
  | n + 1, k => insert ⟨n + 1, k⟩ (lpHaarAncestors n (lpHaarParentIndex n k))

